examples.template:
VStack(spacing: 8) {
    MonarchBulkActionBar(
        count: selection.count,
        totalCount: members.count,
        actions: [
            MonarchBulkAction(id: {{actions.0.id}}, title: {{actions.0.label}}) {},
            MonarchBulkAction(id: {{actions.1.id}}, title: {{actions.1.label}}) {},
            MonarchBulkAction(id: {{actions.2.id}}, title: {{actions.2.label}}) {},
            MonarchBulkAction(id: {{actions.3.id}}, title: {{actions.3.label}}, isDestructive: {{actions.3.destructive}}) {},
        ]
    ) {
        selection.removeAll()
    }
    MonarchDataTable(
        {{caption}},
        rows: members,
        columns: [
            MonarchDataTableColumn({{columns.0}}, isHideable: false, value: { $0.name }),
            MonarchDataTableColumn({{columns.1}}, isHideable: false, value: { $0.team }),
            MonarchDataTableColumn({{columns.2}}, isHideable: false, value: { $0.role }),
        ],
        selection: $selection,
        layout: .list,
        rowLabel: { $0.name }
    )
    Text("Pick an action.")
        .monarchTextStyle(.caption)
}
.frame(height: 700)

