examples.setup:
struct Member: Identifiable, Sendable {
    let id: String
    let name: String
    let team: String
    let role: String
}

private let members = [
    Member(id: "m1", name: "Ana Silva", team: "Support", role: "Agent"),
    Member(id: "m2", name: "Ben Okafor", team: "Support", role: "Lead"),
    Member(id: "m3", name: "Chen Wei", team: "Billing", role: "Agent"),
    Member(id: "m4", name: "Dev Patel", team: "Sales", role: "Manager"),
]
@State private var selection: Set<String> = ["m1", "m3"]

examples.code:
VStack(spacing: 8) {
    MonarchBulkActionBar(
        count: selection.count,
        totalCount: members.count,
        actions: [
            MonarchBulkAction(id: "team", title: "Move to team") {},
            MonarchBulkAction(id: "role", title: "Change role") {},
            MonarchBulkAction(id: "export", title: "Export") {},
            MonarchBulkAction(id: "remove", title: "Remove", isDestructive: true) {},
        ]
    ) {
        selection.removeAll()
    }
    MonarchDataTable(
        "Members",
        rows: members,
        columns: [
            MonarchDataTableColumn("Name", isHideable: false, value: { $0.name }),
            MonarchDataTableColumn("Team", isHideable: false, value: { $0.team }),
            MonarchDataTableColumn("Role", isHideable: false, value: { $0.role }),
        ],
        selection: $selection,
        layout: .list,
        rowLabel: { $0.name }
    )
    Text("Pick an action.")
        .monarchTextStyle(.caption)
}
.frame(height: 700)
